class Solution {
  private int[] tree;
  private int size;

  private void set(int pos, int val) {
    pos += size;
    tree[pos] = val;
    for (pos >>= 1; pos >= 1; pos >>= 1) tree[pos] = Math.min(tree[2 * pos], tree[2 * pos + 1]);
  }

  public long countSubarrays(int[] nums, int k, int m) {
    int n = nums.length, MAXV = 100_001, INF = Integer.MAX_VALUE;
    size = 1;
    while (size < MAXV) size <<= 1;
    tree = new int[2 * size];
    java.util.Arrays.fill(tree, INF);
    int[] total = new int[MAXV], offset = new int[MAXV + 1];
    for (int v : nums) total[v]++;
    for (int v = 0; v < MAXV; v++) offset[v + 1] = offset[v] + total[v];
    int[] occ = new int[n], seen = new int[MAXV];
    int[] cntA = new int[MAXV], cntB = new int[MAXV];
    int distinctA = 0, distinctB = 0, a = 0, b = 0;
    long ans = 0;
    for (int r = 0; r < n; r++) {
      int v = nums[r];
      occ[offset[v] + seen[v]++] = r;
      if (cntA[v]++ == 0) distinctA++;
      while (distinctA > k) {
        if (--cntA[nums[a]] == 0) distinctA--;
        a++;
      }
      if (cntB[v]++ == 0) distinctB++;
      while (b <= r && (distinctB > k || (distinctB >= k && cntB[nums[b]] > 1))) {
        int u = nums[b];
        if (--cntB[u] == 0) {
          distinctB--;
          set(u, INF);
        }
        b++;
      }
      // value of the m-th most recent occurrence of v
      int posM = seen[v] >= m ? occ[offset[v] + seen[v] - m] : -1;
      if (cntB[v] > 0) set(v, posM);
      if (distinctB == k) {
        int t = tree[1];
        long hi = Math.min(b, t);
        if (hi >= a) ans += hi - a + 1;
      }
    }
    return ans;
  }
}
